```tsx
import type { ReactElement } from "react";
import "./AlertBanner.css";

export interface AlertBannerProps {
  message: string;
  onRetry: () => void;
}

export function AlertBanner({ message, onRetry }: AlertBannerProps): ReactElement {
  return (
    <div className="alert-banner" role="alert">
      <p className="alert-banner__message">{message}</p>
      <button type="button" className="alert-banner__retry" onClick={onRetry}>
        Retry
      </button>
    </div>
  );
}
```

```css
.alert-banner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem 1rem;
  padding: clamp(0.75rem, 1.2vw, 1rem) clamp(1rem, 1.6vw, 1.25rem);
  border: 1px solid var(--cresyl);
  border-radius: 12px;
  background-color: var(--slide);
  background-image: linear-gradient(var(--cresyl-wash), var(--cresyl-wash));
  color: var(--ink);
  font-size: clamp(0.9rem, 0.8vw + 0.6rem, 1.05rem);
}

.alert-banner__message {
  margin: 0;
  min-width: 0;
  overflow-wrap: anywhere;
}

.alert-banner__retry {
  flex: none;
  font: inherit;
  font-weight: 600;
  padding: 0.4em 1.1em;
  border: 1px solid var(--myelin);
  border-radius: 999px;
  background: var(--myelin);
  color: var(--slide);
  cursor: pointer;
}
